1	export type Item = {
2	  type: string;
3	  material: string;
4	  enchantment: number;
5	  cursed: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = {
41	  premium: number;
42	};
43	
44	export type ClaimResult = {
45	  payout: number;
46	  remainingCap: number;
47	};
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export type ScenarioResult = {
52	  results: StepResult[];
53	};
54	
55	const BASE_PRICES: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const INSURANCE_VALUES: Record<string, number> = {
65	  sword: 1000,
66	  amulet: 600,
67	  staff: 800,
68	  potion: 400,
69	  rune: 250,
70	  moonstone: 250,
71	};
72	
73	// Expressed as integer percent rather than a 1.1 factor: floating-point
74	// multiplication by 1.1 loses exactness (100 * 1.1 === 115.00000000000001),
75	// while scaling by 110 and dividing by 100 stays exact for these prices.
76	const FIRST_CONTRACT_PERCENT = 110;
77	const WHOLE_PERCENT = 100;
78	const CONTRACT_FEE = 5;
79	
80	const BLOCK_SIZE = 3;
81	const BLOCK_PRICE = 60;
82	
83	const COMPONENT_TYPES = ["rune", "moonstone"];
84	
85	const HIGH_ENCHANTMENT_LEVEL = 5;
86	
87	const applyPercent = (amount: number, percent: number): number =>
88	  (amount * percent) / WHOLE_PERCENT;
89	
90	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
91	  values.reduce((total, value) => total + amountOf(value), 0);
92	
93	const tablePriceOf = (item: Item): number => BASE_PRICES[item.type];
94	
95	// Risk surcharges stack multiplicatively: each one that applies scales the
96	// running price, so a cursed item is 150 % of the table price.
97	const RISK_SURCHARGES: { applies: (item: Item) => boolean; percent: number }[] =
98	  [
99	    { applies: (item) => item.cursed, percent: 150 },
100	    {
101	      applies: (item) => item.enchantment >= HIGH_ENCHANTMENT_LEVEL,
102	      percent: 130,
103	    },
104	  ];
105	
106	const riskAdjustedPriceOf = (item: Item): number =>
107	  RISK_SURCHARGES.filter((surcharge) => surcharge.applies(item)).reduce(
108	    (price, surcharge) => applyPercent(price, surcharge.percent),
109	    tablePriceOf(item),
110	  );
111	
112	const isComponent = (item: Item): boolean =>
113	  COMPONENT_TYPES.includes(item.type);
114	
115	const allOfSameType = (items: Item[]): boolean =>
116	  items.every((item) => item.type === items[0].type);
117	
118	// Only alike components combine into blocks — main items (swords, staves,
119	// potions, amulets) are always priced individually, however many there are.
120	const formsBuildingBlocks = (items: Item[]): boolean =>
121	  items.every(isComponent) && allOfSameType(items);
122	
123	const sumOfItemPrices = (items: Item[]): number =>
124	  sumOf(items, riskAdjustedPriceOf);
125	
126	// Every group of BLOCK_SIZE alike components is priced as one discounted
127	// building block; leftovers keep their individual price.
128	const buildingBlockPriceOf = (items: Item[]): number => {
129	  const blocks = Math.floor(items.length / BLOCK_SIZE);
130	  const itemsInBlocks = blocks * BLOCK_SIZE;
131	  const leftovers = items.slice(itemsInBlocks);
132	  return blocks * BLOCK_PRICE + sumOfItemPrices(leftovers);
133	};
134	
135	const itemsPriceOf = (items: Item[]): number =>
136	  formsBuildingBlocks(items)
137	    ? buildingBlockPriceOf(items)
138	    : sumOfItemPrices(items);
139	
140	const LOYAL_YEARS = 2;
141	const LOYALTY_PERCENT = 80;
142	
143	const isLoyal = (customer: Customer): boolean =>
144	  customer.yearsWithMHPCO >= LOYAL_YEARS;
145	
146	const REPEAT_CONTRACT_PERCENT = 85;
147	
148	// The initial assessment surcharge applies to a customer's first insurance
149	// only; every later contract earns the repeat-customer discount instead.
150	const contractPercentFor = (previousContracts: number): number =>
151	  previousContracts === 0 ? FIRST_CONTRACT_PERCENT : REPEAT_CONTRACT_PERCENT;
152	
153	// Premiums are always rounded up — rounding in MHPCO's favour, per spec.
154	const premiumFor = (
155	  itemsPrice: number,
156	  customer: Customer,
157	  previousContracts: number,
158	): number => {
159	  const contractPrice = applyPercent(
160	    itemsPrice,
161	    contractPercentFor(previousContracts),
162	  );
163	  const discountedPrice = isLoyal(customer)
164	    ? applyPercent(contractPrice, LOYALTY_PERCENT)
165	    : contractPrice;
166	  return Math.ceil(discountedPrice + CONTRACT_FEE);
167	};
168	
169	const quote = (
170	  step: QuoteStep,
171	  customer: Customer,
172	  previousContracts: number,
173	): QuoteResult => ({
174	  premium: premiumFor(itemsPriceOf(step.items), customer, previousContracts),
175	});
176	
177	const DEDUCTIBLE = 100;
178	const CAP_MULTIPLE = 2;
179	
180	const insuranceSumOf = (items: Item[]): number =>
181	  sumOf(items, (item) => INSURANCE_VALUES[item.type]);
182	
183	// A claim's `policy` indexes the quote step that wrote the contract. Resolving
184	// it by narrowing rather than casting keeps the discriminated union honest: a
185	// claim pointing at a non-quote step fails loudly here instead of silently
186	// reading `items` off the wrong shape.
187	const policyAt = (steps: Step[], policyIndex: number): QuoteStep => {
188	  const step = steps[policyIndex];
189	  if (step?.op !== "quote") {
190	    throw new Error(`Step ${policyIndex} is not a policy`);
191	  }
192	  return step;
193	};
194	
195	const FRAGILE_ENCHANTMENT_LEVEL = 8;
196	const FRAGILE_REIMBURSEMENT_PERCENT = 50;
197	
198	// The MHPCO holds that heavily enchanted magic is inherently unstable, and
199	// only reimburses damage to such an item by half.
200	const isFragile = (item: Item): boolean =>
201	  item.enchantment >= FRAGILE_ENCHANTMENT_LEVEL;
202	
203	const UNCOVERED_REIMBURSEMENT_PERCENT = 0;
204	
205	const DRAGON_MATERIAL = "dragon";
206	
207	// Dragon-forged items are reimbursed in full however enchanted they are.
208	const isDragonMade = (item: Item): boolean =>
209	  item.material === DRAGON_MATERIAL;
210	
211	const insuredItemFor = (damage: Damage, insured: Item[]): Item | undefined =>
212	  insured.find((insuredItem) => insuredItem.type === damage.itemType);
213	
214	// Every rate the MHPCO pays at, in precedence order: the first rule that
215	// matches the insured item wins. Dragon-forging is listed above fragility
216	// because it overrides it — a dragon-forged item is paid in full however
217	// heavily enchanted. Anything no rule claims is reimbursed in full.
218	const REIMBURSEMENT_RATES: {
219	  applies: (item: Item) => boolean;
220	  percent: number;
221	}[] = [
222	  { applies: isDragonMade, percent: WHOLE_PERCENT },
223	  { applies: isFragile, percent: FRAGILE_REIMBURSEMENT_PERCENT },
224	];
225	
226	const reimbursementPercentFor = (item: Item | undefined): number => {
227	  if (item === undefined) return UNCOVERED_REIMBURSEMENT_PERCENT;
228	  return (
229	    REIMBURSEMENT_RATES.find((rate) => rate.applies(item))?.percent ??
230	    WHOLE_PERCENT
231	  );
232	};
233	
234	const reimbursementFor = (damage: Damage, insured: Item[]): number =>
235	  applyPercent(
236	    damage.amount,
237	    reimbursementPercentFor(insuredItemFor(damage, insured)),
238	  );
239	
240	// What an incident is worth before the policy's cap is considered: one
241	// deductible comes off the incident total, and a claim never pays out
242	// negative — a damage below the deductible simply pays nothing.
243	const claimedAmountFor = (incident: Incident, insured: Item[]): number =>
244	  Math.max(
245	    0,
246	    sumOf(incident.damages, (damage) => reimbursementFor(damage, insured)) -
247	      DEDUCTIBLE,
248	  );
249	
250	// A policy will only ever pay out twice what its items are insured for.
251	const policyCapOf = (policy: QuoteStep): number =>
252	  CAP_MULTIPLE * insuranceSumOf(policy.items);
253	
254	// However much an incident is worth, a policy pays only what its cap allows.
255	const cappedTo = (cap: number, amount: number): number =>
256	  Math.min(cap, amount);
257	
258	// The cap belongs to the policy, not to the claim: each claim can only draw
259	// on what earlier claims against the same policy have left.
260	const claim = (
261	  step: ClaimStep,
262	  policy: QuoteStep,
263	  remainingCap: number,
264	): ClaimResult => {
265	  const payout = cappedTo(
266	    remainingCap,
267	    claimedAmountFor(step.incident, policy.items),
268	  );
269	  return { payout, remainingCap: remainingCap - payout };
270	};
271	
272	// Steps are processed in order because a claim depletes the cap its policy
273	// has left for later claims.
274	//
275	// A step's position still doubles as the count of contracts written before
276	// it, which over-counts once claim steps intervene; that is a pending test.
277	export const run = (scenario: Scenario): ScenarioResult => {
278	  const remainingCaps = new Map<number, number>();
279	  const results: StepResult[] = [];
280	
281	  scenario.steps.forEach((step, stepIndex) => {
282	    if (step.op !== "claim") {
283	      results.push(quote(step, scenario.customer, stepIndex));
284	      return;
285	    }
286	
287	    const policy = policyAt(scenario.steps, step.policy);
288	    const remainingCap =
289	      remainingCaps.get(step.policy) ?? policyCapOf(policy);
290	    const result = claim(step, policy, remainingCap);
291	    remainingCaps.set(step.policy, result.remainingCap);
292	    results.push(result);
293	  });
294	
295	  return { results };
296	};
