// Steps are processed in order because a claim depletes the cap its policy
// has left for later claims.
//
// A step's position still doubles as the count of contracts written before
// it, which over-counts once claim steps intervene; that is a pending test.
export const run = (scenario: Scenario): ScenarioResult => {
  const remainingCaps = new Map<number, number>();
  const results: StepResult[] = [];

  scenario.steps.forEach((step, stepIndex) => {
    if (step.op !== "claim") {
      results.push(quote(step, scenario.customer, stepIndex));
      return;
    }

    const policy = policyAt(scenario.steps, step.policy);
    const remainingCap =
      remainingCaps.get(step.policy) ?? policyCapOf(policy);
    const result = claim(step, policy, remainingCap);
    remainingCaps.set(step.policy, result.remainingCap);
    results.push(result);
  });

  return { results };
};

